/* Chat kit, reviews, no-escrow and connections. */
test("chat with an unsaved number, then save it",()=>{setView("owner");eq(chatWithNumber("12345").error.slice(0,8),"Enter a ");const r=chatWithNumber("98765 43210");const c=C(r.id);ok(c.unsaved);eq(c.name,"+91 98765 43210");
  eq(chatWithNumber("+91 9876543210").id,r.id,"same number, same chat");ok(saveContact(r.id,"Priya Hyderabad"));eq(c.name,"Priya Hyderabad");ok(!c.unsaved)});
test("customer can message an unknown number and sees the unverified banner",()=>{setView("customer");const r=chatWithNumber("9123456780");openChat(r.id);ok(document.getElementById("app").innerHTML.includes("Not a verified business"))});
test("reply, react, star, edit and delete for everyone",()=>{setView("owner");openChat("c2");const c=C("c2"),i=c.msgs.length-1;S.replyTo={c2:i};S.drafts.c2="Will send the rates today";sendText("c2");const m=c.msgs.find(x=>x.text==="Will send the rates today");ok(m&&m.reply&&m.reply.i===i,"quoted");
  const k=c.msgs.indexOf(m);S.sheet={type:"ckmsg",i:k};act.ckreact({dataset:{e:"👍"}});eq(m.react,"👍");S.sheet={type:"ckmsg",i:k};act.ckstar();ok(m.star);
  S.sheet={type:"ckmsg",i:k};act.ckedit();S.drafts.c2="Will send the rates tonight";sendText("c2");eq(m.text,"Will send the rates tonight");ok(m.edited);
  S.sheet={type:"ckmsg",i:k};act.ckdelall();ok(m.deleted);eq(m.text,"This message was deleted")});
test("forward copies the message with a forwarded mark",()=>{const c=C("c2");post("c2","biz","Rate card attached");const k=c.msgs.length-1;S.sheet={type:"ckmsg",i:k};act.ckfwd();act.ckfwdto({dataset:{id:"c7"}});const f=C("c7").msgs[C("c7").msgs.length-1];ok(f.fwd);eq(f.text,"Rate card attached")});
test("attachments and poll voting",()=>{openChat("c2");const c=C("c2"),n=c.msgs.length;act.ckdoc();act.ckloc();act.ckvoice();eq(c.msgs.length,n+3);
  S.sheet={type:"ckpoll"};render();document.getElementById("pq").value="Pickup day?";document.getElementById("po0").value="Mon";document.getElementById("po1").value="Tue";act.ckpollsend();const p=c.msgs[c.msgs.length-1];eq(p.type,"poll");
  act.ckvote({dataset:{i:c.msgs.length-1,o:1}});eq(p.poll.opts[1].v,1);act.ckvote({dataset:{i:c.msgs.length-1,o:0}});eq(p.poll.opts[1].v,0);eq(p.poll.opts[0].v,1)});
test("block stops sending; pin, mute and archive",()=>{openChat("c9");act.ckblock();const n=C("c9").msgs.length;S.drafts.c9="hello";sendText("c9");eq(C("c9").msgs.length,n);act.ckunblock();
  act.ckpin();ok(C("c9").pinned);act.ckmute();ok(C("c9").muted);act.ckarchive();ok(C("c9").archived);S.filter="All";render();ok(!document.querySelector('.crow[data-id="c9"]'),"archived chat hidden");act.filt({dataset:{v:"Archived"}});ok(document.querySelector('.crow[data-id="c9"]'));C("c9").archived=false;C("c9").pinned=false;C("c9").muted=false;S.filter="All"});
test("group creation and member replies",()=>{setView("owner");S.sheet={type:"ckgroup",pick:["c2","c7"]};render();document.getElementById("gname").value="Pongal buyers";act.ckgcreate();const g=S.chats.find(c=>c.name==="Pongal buyers");ok(g&&g.kind==="group");eq(g.members.length,2)});
test("status: post one and a buyer orders from it",()=>{setView("owner");S.sheet={type:"ckstatusnew"};act.ckstpost({dataset:{id:"p4"}});ok(S.statuses.find(s=>s.biz==="st").items.some(i=>i.pid==="p4"));
  setView("customer");act.ckstopen({dataset:{b:"st"}});eq(S.sheet.type,"ckstatus");act.ckstbuy();eq(S.sheet.type,"order");S.sheet=null});
test("AI search opens only from the top button",()=>{setView("owner");S.aiOpen=false;render();ok(!document.querySelector(".aibar"));act.aitoggle();ok(document.querySelector(".aibar"));act.aitoggle();ok(!document.querySelector(".aibar"))});
test("only buyers can review, and reviews wait for BOC",()=>{BOCStore.reset();setView("customer");eq(canReview("ld"),false);ok(submitReview({biz:"ld",stars:5,text:"Lovely salon visit"}).error);
  ok(canReview("am"),"Meera bought from the pharmacy");const r=submitReview({biz:"am",stars:4,text:"Quick delivery, sealed strips",order:"ORD 0187"}).review;eq(r.status,"pending");ok(!reviewsFor("am").some(x=>x.id===r.id),"not shown yet");
  BOCStore.patch("admin",a=>{a.reviews.find(x=>x.id===r.id).status="published";return a});ok(reviewsFor("am").some(x=>x.id===r.id));BOCStore.reset()});
test("low rating goes to the seller first",()=>{BOCStore.reset();BOCStore.patch("admin",a=>{a=a||structuredClone(SEED.admin);a.reviews.unshift({id:"RV-T1",biz:"st",author:"Kiran",order:"ORD 0150",stars:2,text:"Wrong colour sent",status:"seller"});return a});
  setView("owner");S.tab="pending";render();ok(document.getElementById("app").innerHTML.includes("Customer reviews to put right"));act.rvfix({dataset:{id:"RV-T1"}});eq(BOCStore.load().admin.reviews[0].status,"seller-replied");BOCStore.reset()});
test("no escrow: an online order is paid straight to the seller",()=>{setView("customer");const o=placeOrder("c1",[{pid:"p4",qty:1,price:2400}],"upi",78);eq(o.pay,"paid");ok(o.method.includes("via"));ok(!/BOC Protect|held/i.test(document.getElementById("app").innerText))});
test("connections respect the plan and keep one way to get paid",()=>{const was=S.plan;S.plan="free";S.conns={upi:true};S.sheet={type:"cx",v:"razorpay"};act.cxgo({dataset:{v:"razorpay"}});ok(!S.conns.razorpay);ok(/Upgrade to Growth/.test(S.sheet.err));
  S.plan="pro";S.sheet={type:"cx",v:"razorpay"};act.cxgo({dataset:{v:"razorpay"}});ok(S.conns.razorpay);S.payGw="upi";S.sheet={type:"cx",v:"upi"};act.cxoff({dataset:{v:"upi"}});eq(S.payGw,"razorpay");S.plan=was;S.sheet=null});
